style.css:
@-moz-document domain("dafont.com") {
:root { color-scheme: dark !important; }

  /* ---- Base surfaces ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  /* The 404 page (and only the 404 page) paints a bright penguin photo as a
     `body` background-image, which our light body text then sits on unreadably.
     It's a raster, so bg-color and gradient audits both miss it. */
  body { background-image: none !important; }
  /* NOTE: `.contain` is NOT a layout wrapper — it is the little pink "Accents"/
     "Euro" badge on each font row. Blanking it strips the pill and drops black
     glyphs straight onto the red bar, so it must stay out of this reset. */
  .layout, .container, .width, .minwidth, .out,
  #content, table, tbody, tr, td {
    background-color: transparent !important;
  }

  /* ---- Soften all default light/black borders ---- */
  * { border-color: #2d333b !important; }
  /* DaFont uses `solid #fff` borders as invisible spacers on its white page — and the
     font-detail page's author-banner wrapper spells the same trick `solid white`. The
     remap above turns both into visible grey slabs; keep them invisible. */
  div[style*="solid #fff"], div[style*="solid white"] {
    border-color: transparent !important;
  }
  /* Same trick spelled as TEXT: the "Google Search on dafont.com" block that closes every
     `search.php?q=` page ends with a bare `<span style="color:#fff">.</span>` layout shim.
     Invisible on the white page, a stray white dot under the search box on dark. It is the
     only inline white text on the site, so the shape can stay unscoped. */
  span[style*="color:#fff"] { color: transparent !important; }
  /* The blanket reset above also swallows every BRAND-RED rule DaFont draws
     (`#menuthemes table` 4px frame, the .titlebar/h1/.headerpage hairlines, the
     current-page pagination pill, the new-fonts date divider). Give them back the
     softened brand red — a grey slab where the site drew red is a lost signal that
     no contrast or luminance check can see. */
  #menuthemes table, .menupselect,
  .titlebar, h1, h3.headerpage, .headindex, .select, .new_date,
  .help {
    border-color: #b3322f !important;
  }
  /* Forum thread status ring: DaFont encodes reply state as an inline border-color
     on .thumb_cont (#d4d4d4 none / #fc3 has replies / #3d6 answered) and repeats the
     same three hues in the .square legend swatches below the list. Flattening them
     to grey drops the state AND breaks the legend, so keep the two chromatic ones
     verbatim; the neutral #d4d4d4 ring stays the softened grey from the reset above.
     `forum/requests.php?f=<slug>` draws the same key on `div.thumb` instead of
     `.thumb_cont`, so both classes must be named. */
  div.thumb_cont[style*="#fc3"], div.thumb[style*="#fc3"] { border-color: #fc3 !important; }
  div.thumb_cont[style*="#3d6"], div.thumb[style*="#3d6"] { border-color: #3d6 !important; }
  /* Inside a thread, a solved font request gets an "Identified font:" callout drawn
     as a bare inline-styled element with `border:2px solid #3d6` — the same success green
     as the answered-thread ring — and its amber `#fc3` twin marks "Suggested font:".
     The blanket border reset greys both out, dropping the solved/suggested signal.
     NOT `div[…]`: `/forum/user.php?user=` draws the same two callouts as a <span>. */
  [style*="solid #3d6"] { border-color: #3d6 !important; }
  [style*="solid #fc3"] { border-color: #fc3 !important; }
  /* The empty-state notice ("No font with the limits you chose:") on author/listing
     pages is a bare inline-styled div framed top AND bottom with `10px solid #cc0000`
     brand red. The blanket reset greys that frame, dropping the alert's entire visual
     emphasis (its white bg is darkened and its heading stays salmon, but the box reads
     as a flat dark strip). Give the red edge back, softened for dark. */
  div[style*="solid #cc0000"], div[style*="solid #CC0000"] {
    border-color: #b3322f !important;
  }
  /* The .square swatches (forum-list legend + the per-page status boxes in the
     pagination) repeat those same three hues, but as a BACKGROUND, not a border —
     the reset above only softens borders, so the neutral #d4d4d4 swatch stayed a
     bright light-grey square glaring on dark AND no longer matched its softened-grey
     ring. Bring it in line; the two chromatic swatches keep their inline #fc3/#3d6. */
  span.square[style*="#d4d4d4"] { background-color: #2d333b !important; }
  /* The status-filter chips above the thread list encode "you are here" PURELY in the
     border: `.curgroup{border:1px solid #ccc}` (the selected filter) vs
     `.othgroup{border:1px solid #fff}` (the rest — white-on-white, i.e. an INVISIBLE
     spacer). The blanket reset paints both the same grey, so every chip grows an
     identical box and the selected-filter cue vanishes entirely. Restore the split:
     the others go back to invisible, the current one keeps a clearly visible ring. */
  .othgroup { border-color: transparent !important; }
  .curgroup { border-color: #8b949e !important; }

  /* ---- Links ---- */
  a { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }
  /* DaFont uses many black-text links (font names, nav); keep them readable */
  a.tdn, a.tdn.black, .lv2right a, .noindex a, .menu a, .catpp a,
  .headindex a, .dfsmall a, .donate a, .fleche a {
    color: #5fb0e6 !important;
  }
  a.tdn:hover, .lv2right a:hover, .noindex a:hover, .menu a:hover,
  .catpp a:hover, .dfsmall a:hover { color: #9bd4ff !important; }
  /* The language row is `a.flag{color:#000; opacity:.60}` — deliberately faded
     chrome, and the fade is its own hover affordance (`a.flag:hover{opacity:1}`).
     It also carries `.tdn`, so the link colours above would paint it #5fb0e6 at
     60% alpha over the base = 3.5:1, a fail. Keep it body-grey in BOTH states
     (4.75:1 faded, 8:1 hovered); must sit after `a:hover` to win the 0,1,1 tie. */
  a.flag, a.flag:hover { color: #c4cdd6 !important; }

  /* ---- Brand red, refined for dark ---- */
  /* DaFont's raw #cc0000 is garish on near-black — keep the identity, soften it. */
  .dfbg, .lv1left, .lv1right, .lv2left {
    background-color: #b3322f !important;
    color: #ffffff !important;
    border-color: #8f2724 !important;
  }
  .dfbg a, .lv1left a, .lv1right a { color: #ffffff !important; }
  .headindex, .headindex a { color: #e86a64 !important; }
  /* "100% Free" red accent text */
  a[style*="color:#c00"], a[style*="color:#C00"] { color: #e86a64 !important; }

  /* ---- Logo block keeps brand red ---- */
  .logo, td.dfbg { background-color: #b3322f !important; }

  /* ---- Top menu / category navigation ---- */
  .menu { background-color: transparent !important; }
  #menuthemes, .colthemes { background-color: transparent !important; }
  .metacat, .metacat.dfbg {
    background-color: #b3322f !important;
    color: #ffffff !important;
  }
  /* Category-nav links sit in a bar that also carries .dfsmall, so the
     `.dfsmall`-scoped muted rules further down must never out-specify this pair
     (0,1,1) / (0,2,1) — see the note on the muted-text block. */
  .metacat a, .metacat.dfsmall a { color: #ffffff !important; }
  .catpp { background-color: transparent !important; color: #c4cdd6 !important; }
  /* `.catpp a:hover` hardcodes a light-grey #e3e3e3 pill (drawn for the white page).
     Neutralizing `.catpp` alone leaves it: the hovered link becomes a glaring white
     chip with our light-blue label on it (~1.5:1). Hover-only, so no load-time scan
     ever sees it. */
  .catpp a:hover { background-color: #21262d !important; }
  /* The CURRENT subcategory is the only `#menuthemes b` on the page and DaFont paints
     it brand red — that red is the entire "you are here" cue (its siblings are links).
     Our broad `b, strong` rule greyed it out. Scoped to .catpp so the .metacat headers
     on the red bars keep the white text set at the end of this sheet. */
  .catpp b { color: #e86a64 !important; }

  /* ---- Search form + submit ---- */
  .search_form, input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  ::placeholder { color: #8b949e !important; }
  input[type="submit"], button {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, button:hover { background-color: #2d333b !important; }
  /* Author/profile "Send a private message" button (a.pm) hardcodes a light
     #f9f9f9 background — a white pill glaring on the dark page. Raise it to the
     same elevated dark control surface as the neighbouring form buttons. */
  .pm {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .pm:hover { background-color: #2d333b !important; }
  /* Author/profile header block is a classless inline-styled #f0f0f0 panel (red
     top border) carrying the username, avatar and "Registered before …" line —
     a light bar glaring across the top with the (already-remapped light) username
     reading light-on-light. Raise it to an elevated dark surface; its red border
     is softened by the global border rule, consistent with other bars. */
  div[style*="border-top:1px solid #CC0000"][style*="background:#f0f0f0"] {
    background: #1c2128 !important;
    border-top-color: #b3322f !important;
  }
  /* Author-profile "User comment" box: a classless inline-styled div
     `border-left:5px solid #ddd; background:#f0f0f0` holding the author's
     free-text bio, present only when they filled the field. The light-grey
     panel leaves our remapped light body text reading light-on-light (~1.45:1).
     Raise it to the elevated dark surface like the header panel above; its #ddd
     quote bar is already softened by the global border reset. */
  div[style*="border-left:5px solid #ddd"] {
    background: #1c2128 !important;
  }
  /* Option-bar <select> caret: DaFont hides the native arrow (`-webkit/-moz-appearance:
     none` on `.perso select`) and draws its own as a background raster — `/img/dropdown.gif`,
     a PURE-BLACK 9x5 triangle (measured mean luminance 0, i.e. 1.3:1 on our dark control),
     swapped on :hover for `/img/dropdown_hover2.png`, a fully opaque 17x20 LIGHT tile
     (mean 208) that glares at the field's edge. Both are background-IMAGES sitting on a
     correctly dark background-color, so every colour scan reads the select as clean.
     Redraw the same caret in CSS, in both states. */
  .perso select, .perso select:hover {
    background-image:
      linear-gradient(45deg, transparent 50%, #c4cdd6 50%),
      linear-gradient(135deg, #c4cdd6 50%, transparent 50%) !important;
    background-position: right 8px top 50%, right 4px top 50% !important;
    background-size: 4px 4px !important;
    background-repeat: no-repeat !important;
  }
  /* Listing option-bar checkbox pill ("Show variants") — DaFont wraps it in a
     hardcoded light-grey (#ebebeb) .form_elt_bg box. Left alone it glares on the
     dark bar AND our light `label` color turns the caption light-on-light. Raise
     it to the same elevated dark control surface as the neighbouring selects. */
  .form_elt_bg {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* ---- Font preview samples (background-image PNGs: black-on-white) ---- */
  /* Inverting turns the black glyphs into light text that reads cleanly on dark,
     while preserving the exact glyph shapes of each font. */
  /* The option bar's "Size" <select> (name=psize) swaps the preview class per row:
     m→.preview (default), l→.preview_l, s→.preview_s, xs→.preview_xs, each pulling
     from its own raster dir (/img/preview_l/…). Only the default was inverted, so
     picking any other size shipped a full-width WHITE slab per font row on every
     listing, search, new and font-detail page. The class carries no shared hook and
     the raster is a background-IMAGE, so no colour scan sees it. */
  /* `mix-blend-mode` is what keeps the raster's own field from becoming a visible plate:
     inverting white lands it on rgb(20,20,20), a few points off the rgb(20,24,29) base, so
     every preview draws a dark rectangle around its glyphs. Blending in `lighten` against the
     base resolves that field back to the base exactly while the light glyphs, being brighter
     than it, come through untouched. Requires the raster to be dark-on-light, as DaFont's
     generated previews and character maps all are. */
  .preview, .preview_s, .preview_xs, .preview_l {
    filter: invert(0.92) !important;
    mix-blend-mode: lighten !important;
    border-radius: 4px !important;
  }
  /* Font-page character map is a black-on-white <img> — invert it the same way */
  img[src*="/img/charmap/"], img[src*="/img/preview/"],
  img[src*="/img/preview_s/"], img[src*="/img/preview_xs/"],
  img[src*="/img/preview_l/"] {
    filter: invert(0.92) !important;
    mix-blend-mode: lighten !important;
    border-radius: 4px !important;
  }

  /* ---- Black icon rasters (pagination arrows, dropdown caret) ---- */
  /* These GIFs are solid-black glyphs on transparent, drawn for the white page;
     on dark they render as invisible dark-on-dark shapes. Raster, so no colour
     audit sees them. Invert to white glyphs. */
  /* out3_black.gif is the BLACK twin of out3.gif (the white one DaFont uses on its red
     bars) — it marks external author links on the plain page. Measured mean luminance
     0/255, so on dark it is an invisible glyph. Do NOT invert out3.gif: that one is
     already white. */
  /* The forum adds five more of the same kind: the previous-page arrow (the twin of
     page_suivante, measured mean luminance 41), the skip-to-topic chevrons (42), the
     post "Quote" speech bubble (0) and the "Back to the list" arrow (0). Leaving them
     out shipped a bright white NEXT arrow beside a near-invisible PREVIOUS one.
     copy.png (0) is the glyph-browser "Copy glyph" icon, which sits on our own dark
     button rather than the light UA one it was drawn for. */
  img[src*="/img/dropdown.gif"],
  img[src*="/img/page_suivante.gif"],
  img[src*="/img/page_precedente.gif"],
  img[src*="/img/theme_suivant.gif"],
  img[src*="/img/skip_next.gif"],
  img[src*="/img/skip_previous.gif"],
  img[src*="/img/quote.gif"],
  img[src*="/img/quote.png"],
  img[src*="/img/goto.gif"],
  img[src*="/img/copy.png"],
  img[src*="/img/out3_black.gif"] {
    filter: invert(1) !important;
  }
  /* Two of the glyph rasters are MID-grey rather than black: hide.gif (the ✖ beside
     "Reinitialize" on the listing option bar, measured mean luminance 102) and back_list.gif
     (the "Back to Font page" chevrons on the glyph browser, 78). On the white page they read
     5.7:1 / 8.4:1 beside their labels; left alone on dark they drop to 2.8:1 / 1.8:1, dimmer
     than the text they belong to. Inverting restores the site's ratio. */
  img[src*="/img/hide.gif"], img[src*="/img/back_list.gif"] { filter: invert(1) !important; }
  /* /img/top.gif is the pure-white arrow pair in the "Back to top" bar below, drawn for the
     #e6e6e6 strip it sits on — 1.06:1 there, a deliberately faint affordance. On the darkened
     strip it renders at 14:1 and becomes the loudest thing in the footer. */
  img[src*="/img/top.gif"] { opacity: 0.22 !important; }

  /* ---- Glyph browser (`<font>.charmap` — the "View all glyphs (N)" page) ---- */
  /* A page served by its own stylesheet (`charmap.css`) and left entirely unthemed.
     Every glyph is a <canvas> painted with a PURE-BLACK outline on a transparent
     bitmap (measured mean luminance 0), so all N cells render as invisible black-on-
     dark shapes. Canvas art is pixels: no colour scan can see it. Invert it like the
     preview/charmap rasters above — `invert()` leaves alpha alone, so the transparent
     cell background is untouched and only the glyph flips to light. */
  .item canvas, #glyph-display canvas {
    filter: invert(0.92) !important;
  }
  /* Cell hover and the open ("selected") cell are both `#f8f9f9` — a solid white tile
     on the dark grid, and both are states no load-time scan ever reaches. DaFont
     paints the two identically, so keep them identical here too. */
  .item:hover, .item.selected {
    background-color: #21262d !important;
  }
  /* Clicking a glyph opens `#glyph-full`: a full-width 230px `background-color:white`
     bottom sheet (the `div.sticky2{background:yellow}` on the same element loses on
     specificity). It carries a LIGHT `#CCC` drop shadow as its only separator, and its
     text is classless divs under DaFont's base `div {color:#000}`. */
  #glyph-full {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-top: 1px solid #2d333b !important;
    box-shadow: 0 -5px 10px -6px #000 !important;
  }
  #glyph-full div, #glyph-full span { color: #c4cdd6 !important; }
  /* The sheet's ✖ close button carries a JS-written inline `background:rgb(255,255,255)`
     — invisible on the white panel it was drawn for, a grey slab under our own light ✖
     on dark. The safety net at the end of this sheet matches the literal `#fff`, not the
     rgb() form the DOM ends up with, so it never reaches this one. */
  #glyph-hide { background: transparent !important; }
  /* The "Copied!" confirmation is `color:grey` — 4.1:1 on that sheet. Must out-specify
     the `#glyph-full div` rule above (1,0,1), or it renders at full body strength and
     the transient toast stops reading as secondary. */
  #glyph-full #infoGlyph_copy { color: #8b949e !important; }
  /* Page pills (only built for fonts over 3000 glyphs) are bare <div>s, so the base
     `div {color:#000}` leaves them black on dark, and the blanket border reset above
     greys out the `1px solid #c00` ring that is their whole hover affordance. */
  .charmapPage_button { color: #c4cdd6 !important; }
  .charmapPage_button:hover {
    color: #e6edf3 !important;
    border-color: #b3322f !important;
  }
  /* The font-parsing spinner is a `#f3f3f3` ring with a `#444` head — the border reset
     paints both `#2d333b`, leaving it spinning with nothing to see. */
  #loader {
    border-color: #2d333b !important;
    border-top-color: #8b949e !important;
  }

  /* ---- Download box + button ---- */
  /* `filter` on `.preview` above creates a STACKING CONTEXT, which promotes the
     preview row — including the full-width transparent <a> DaFont lays over it —
     above the statically-positioned .dlbox that overlaps it. The Télécharger /
     Faire-don buttons then stop being hoverable AND clickable: the click lands on
     the preview link and navigates to the font page instead of downloading. This
     is a hit-test regression, invisible to every colour/contrast scan. Give the
     download box its own stacking context so it paints back on top. */
  .dlbox {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
    position: relative !important;
    z-index: 1 !important;
  }
  .dl {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  .dl:hover { background-color: #2d333b !important; color: #ffffff !important; }
  /* DaFont's whole hover affordance on both buttons is `border: 2px solid #c00`.
     The blanket border reset repaints it grey, so `.donate` (which has no background
     of its own) ends up with NO hover feedback at all. Give the red edge back. */
  .dl:hover, .donate:hover { border-color: #b3322f !important; }
  .donate:hover { background-color: #21262d !important; }

  /* ---- Font-file caption bar (glyph map header) + filename chip ---- */
  /* Original is a light grey→white gradient with white text — recolor to a dark
     brand-tinted bar so the white filename text reads. */
  div[style*="linear-gradient(to right,#c8c8c8"],
  div[style*="linear-gradient(to right, #c8c8c8"] {
    background: linear-gradient(to right, #8f2724, #b3322f) !important;
    color: #ffffff !important;
  }
  .filename {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Title / breadcrumb / pagination band ---- */
  /* Original is a light grey band (rgb 240,240,240) sitting above each listing,
     detail and search page — raise it to an elevated dark surface with readable
     text. Detail pages use a bare <h1> for the same band. */
  .titlebar, h1 {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  .titlebar a { color: #e6edf3 !important; }
  /* DaFont paints the page title itself in brand red (`h1, .headerpage {color:#c00}`
     and `.dffont2 {color:#c00}`), and on the search page the echoed query sits inside
     it as `<div class="dffont2"><b><i>query</i></b></div>` — our broad `b, strong` and
     `p, td, i` rules repaint those children grey. Keep the whole title red. */
  h1, h1 a, .dffont2, .titlebar .dffont2,
  .dffont2 a, .dffont2 b, .dffont2 i { color: #e86a64 !important; }
  /* Forum section-title band (h3.headerpage) is a light-grey bar like .titlebar,
     with DaFont-red heading text — raise to an elevated dark surface, keep red. */
  h3.headerpage {
    background-color: #1c2128 !important;
    color: #e86a64 !important;
  }
  /* Forum thread title is a bare <h2> on the base dark bg — DaFont's base
     `body,div,td:{color:#000}` leaves it black-on-dark. Lift it to readable. */
  h2, h2 a { color: #e6edf3 !important; }
  /* Forum post header strip (.hmessage) is a hardcoded light-grey #e9e9e9 bar
     carrying the username/avatar/date — raise to an elevated dark surface. Its
     .date child keeps DaFont's black inline color, so remap that too. */
  .hmessage {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* Every post carries a "Link to this post" permalink of the form
     `read/<id>-<n>/<slug>?highlight=<postid>`, and the quote-jump chevrons use the same
     URL. On that page DaFont marks the target post by tinting ONLY its header strip
     `background:#ff9` — the sole "this is the post you came for" cue. The .hmessage rule
     above flattens it to the same elevated grey as every other post. Keep it as the dark
     amber this sheet already uses for the forum's other yellow states (.thumb_text
     #fff5af). Server-rendered but query-gated, so a bare thread load never shows it. */
  .hmessage[style*="background:#ff9"] { background-color: #3a2f0c !important; }
  .date, .hmessage .date { color: #c4cdd6 !important; }
  /* A normal poster's name is an <a> and picks up the link colour, but a DELETED
     account renders as a bare text node under DaFont's base `div {color:#000}` —
     pure black on the elevated .hmessage bar. Colour the wrapper and the name span. */
  div.user, .username { color: #c4cdd6 !important; }
  /* Forum post message body (.body) carries the actual post text as classless
     nodes under DaFont's base `color:#000` — black-on-dark unless remapped.
     `/forum/user.php?user=` (a poster's own post list, linked from every avatar)
     renders the identical text as `.body_alt`, which forum4.css declares with no
     colour of its own — so that whole page's content was pure black on dark. */
  .body, .body p, .body div,
  .body_alt, .body_alt p, .body_alt div { color: #c4cdd6 !important; }

  /* ---- Body content text + form/control labels ---- */
  /* DaFont hardcodes black on much of its content (the "Note of the author"
     block, the option-bar labels above search/size/sort, the install-help OS
     labels, dfsmall license rows) — these stay black-on-dark unless remapped.
     None of these <b>/<strong>/<label> live inside the red brand bars (those
     use .dfbg / .lv* which keep their own white text), so this is safe. */
  b, strong, label, .perso, .perso b {
    color: #c4cdd6 !important;
  }
  /* DaFont's stylesheet sets `body,div,td,p,select {color:#000}` as the base
     text color — our html/body override only reaches <body>, so plain content
     text (FAQ paragraphs + headings, forum stats columns, login-form labels,
     generic table cells) stays black-on-dark. Remap that whole set to readable.
     Brand bars (.dfbg/.lv*) keep their own white via higher class specificity. */
  p, td, i, blockquote, .librub { color: #c4cdd6 !important; }
  /* The "Note of the author" block is classless — its only stable hook is the
     quote-style left border DaFont sets inline. Recolor its text and that border. */
  div[style*="border-left:5px solid #eee"],
  div[style*="border-left:5px solid #eee"] * {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* …but that `*` (0,1,1) also swallows the author's own website link inside the
     block, so it read as prose and lost DaFont's `a:hover{color:#c00}`. Anchors
     are links: (0,1,2) beats the wildcard. */
  div[style*="border-left:5px solid #eee"] a { color: #5fb0e6 !important; }
  div[style*="border-left:5px solid #eee"] a:hover { color: #9bd4ff !important; }
  /* Main content column ("margin-left:140px") holds classless body text such as
     the install-instruction steps and the FAQ's bare "Votre question…" text
     node directly on the column div — keep both the column and its classless
     descendants readable on dark. */
  div[style*="margin-left:140px"],
  div[style*="margin-left:140px"] li,
  div[style*="margin-left:140px"] div:not([class]) { color: #c4cdd6 !important; }
  /* …but the author-profile username is exactly such a classless div, inline-coloured
     brand red — it is that page's only heading and the rule above greys it out. The
     column-scoped selectors below match its specificity (0,2,2) and come later, so
     they win the tie; the bare ones cover the same div outside the column.
     (`border-top:1px solid #CC0000` on the wrapper does NOT contain the substring
     `color:#CC0000`, so the wrapper's background is untouched.) */
  div[style*="color:#CC0000"],
  div[style*="color:#cc0000"],
  div[style*="margin-left:140px"] div[style*="color:#CC0000"],
  div[style*="margin-left:140px"] div[style*="color:#cc0000"] {
    color: #e86a64 !important;
  }
  /* …and the authors page wraps ONE of its two red column headings in a <b>
     ("Top Authors"), which our `b, strong` rule repaints grey — while its twin
     ("Last referred authors", a bare text node in the same red div) stays red.
     Direct child only: the nested `.tdh` period switcher inside that div carries
     its own `color:#000` and its <b> must keep the muted grey, not turn red. */
  div[style*="color:#CC0000"] > b,
  div[style*="color:#cc0000"] > b,
  div[style*="color:#CC0000"] > strong,
  div[style*="color:#cc0000"] > strong {
    color: #e86a64 !important;
  }
  /* Listing subtitle ("- N font files") + truncation ellipsis */
  .lv2right, .cut { color: #c4cdd6 !important; }
  /* New-fonts page date divider (.new_date): the date keeps DaFont's red but the
     raw #cc0000 is too dim on near-black — lift it; its inline color:#000 font-
     count child ("N polices") is otherwise invisible on dark. */
  .new_date { color: #e86a64 !important; }
  .new_date span { color: #c4cdd6 !important; }

  /* Forum thread-list thumbnail caption tiles (.thumb_text): inline light bgs
     (#eee default, #cfb answered-green, #fff5af highlighted) wash the .tdh title
     and the bare "N reply" text node out. Raise to an elevated dark surface and
     keep the green "answered" status as a dark-green tint. */
  /* The three inline bgs are a status key matched by the .square legend swatches:
     #eee = no reply, #fff5af = has replies, #cfb = answered. Keep all three
     distinguishable — collapsing #fff5af into the neutral surface silently drops
     the "has replies" state the yellow legend swatch still promises. */
  /* background-COLOR, not the `background` shorthand: a fourth state ("probably not a
     font") is drawn as `#eee` plus a `stripes_alt.png` diagonal hatch, and the
     shorthand would reset that background-image away along with the colour. */
  .thumb_text { background-color: #1c2128 !important; color: #c4cdd6 !important; }
  .thumb_text[style*="#fff5af"] { background-color: #3a2f0c !important; }
  .thumb_text[style*="#cfb"] { background-color: #16361f !important; }
  /* `forum/requests.php` hangs a hover tooltip off every thumbnail: `span.label`, a solid
     #ccffbb callout the site fills with black text. Its content is a `.dfsmall` span, so the
     muted-text rule further down repaints it #c4cdd6 on that pale green (1.4:1). Same shape as
     the yellow div.notif banner — keep the site's colour, darken the ink. The tooltip is
     parked at margin-left:-9999px until hover, so no load-time scan reaches it. */
  span.label, span.label * { color: #14181d !important; }

  /* ---- Inline #e9e9e9 panels (comment zebra rows + "not a font" callout) ---- */
  /* `font-comment.php` zebra-stripes its comment list with an inline
     `background:#e9e9e9` on every other row — 87 of them on a busy font — and the
     forum thread page uses the same colour for the "This is most probably not a font"
     callout. Our remapped light body text lands on both at ~1.4:1. Match the
     background-COLOR only: the callout layers a `stripes_alt.png` hatch on top that
     marks the state, and the `background` shorthand would erase it. */
  div[style*="background:#e9e9e9"] {
    background-color: #1c2128 !important;
  }
  /* The zebra's other half: the alternating row is a bare `background:#fff`, which the
     white-cell safety net at the end of this sheet lifts to the SAME elevated surface as
     the #e9e9e9 row — 174 identical rows, the stripe gone. Drop the white ones to the
     base so the alternation survives. The `padding:9px 3px` half of the selector keeps it
     to the comment rows (and takes it to (0,2,1), over the net's (0,1,0)). */
  div[style*="padding:9px 3px"][style*="background:#fff"] {
    background-color: #14181d !important;
  }
  /* The "author of <font>" badge on a comment keeps DaFont's yellow `background:#ff0`,
     but our `.dfsmall b` rule repaints its text light grey — 1.9:1 on that yellow.
     Same shape as the div.notif banner below: keep the yellow, darken the text. */
  span[style*="background:#ff0"] { color: #14181d !important; }

  /* ---- Hover affordances our own resets flattened ---- */
  /* `a.post_button:hover` (forum "New Topic" / "Reply") is `border:2px solid #c00`;
     the blanket border reset repaints it grey, leaving only a 1px→2px thickening. */
  a.post_button:hover { border-color: #b3322f !important; }
  /* `.metacat:hover {background:#d11}` brightens the category header bars; our own
     `.metacat` background rule outranks it, so the bars stop reacting to hover. */
  .metacat:hover { background-color: #c93b38 !important; }

  /* ---- Secondary / muted text ---- */
  .light { color: #8b949e !important; }
  /* Text only — keep `a` OUT of this list. Anything of the shape `.dfsmall a…`
     here scores at least (0,2,1) and beats both the `.dfsmall a` link rule and the
     `.dfsmall a:hover` rule at the top of this sheet, which paints every .dfsmall
     link the same grey as the prose around it and erases DaFont's
     `a:hover{color:#c00}` — the top-left Login/Register pair, the footer row and
     the font author's own website link end up with no hover feedback at all.
     The red brand bars don't need such a rule: `.metacat.dfsmall a` (0,2,1) and
     `.dfbg a` (0,1,1) already outrank the plain `a` rule. */
  .dfsmall, .dfxsmall, .points, .dfsmall b, .dfsmall label {
    color: #c4cdd6 !important;
  }
  /* DaFont mutes its secondary numbers and captions with greys of its own: `.light` and
     `.grey` (both #888), the forum-stats share column (`td.tot {color:#999}`), and the
     ad-disclosure labels it writes inline ("Google Ads of <author>", "Ad by <author>").
     `.light` is remapped above, but the `.dfsmall` rule right here ties it at (0,1,0) and
     comes later — so every `.dfsmall.light` ("Edited on …" under a forum post) and every
     `.dfsmall.grey` (the 100 download counts on authors.php) rendered at full body
     strength, erasing the muted/primary split. Match at (0,2,0) or higher, and after, so
     the tie cannot come back. Not `[style*="color:#777"]`: the login form's section
     heading uses that one as an EMPHASIS, and #777 is 3.9:1 here anyway. `div.nr`
     ("Forum: <link>" above every post on `/forum/user.php?user=`) is forum4's #777 and
     measures 3.61:1 on the .hmessage bar — a real fail, not just a lost distinction;
     `div.` keeps it off `a.nr` (the post permalink), which stays a link. `.orig_url`
     is the same shape at #999. */
  .dfsmall.light, .grey, .dfsmall.grey, td.tot, div.nr, div.orig_url,
  div.dfsmall[style*="color:#888"], div.dfsmall[style*="color:#999"] {
    color: #8b949e !important;
  }
  .tdh, .black, td.black { color: #c4cdd6 !important; }
  /* The "View all glyphs (N)" row on a font page opens with a bare
     `<span style="color:#c8c8c8">➥</span>` bullet — 1.55:1 against the black label it
     precedes on the white page, i.e. deliberate decoration. Carried over verbatim it
     renders at 12.6:1, level with the light label, and the recessive/primary split is
     gone. Same class as the `/img/top.gif` arrows dimmed above. The site's other
     `#c8c8c8` is the caption-bar gradient, which is a `background`, not a `color`. */
  span[style*="color:#c8c8c8"] { color: #3d444d !important; }
  /* The SELECTED country on `authors.php?cc=NNN` is the one entry of that 200-item list
     rendered as `<b style="color:#CC0000">` instead of a link — the red IS the "you are
     here" cue. The `div[style*="color:#CC0000"]` rules above never reach it: the inline
     style is on the <b> itself, not an ancestor div. Ties `.dfsmall b` (0,1,1), so it
     has to stay after that rule to win on source order. */
  b[style*="color:#CC0000"], b[style*="color:#cc0000"],
  strong[style*="color:#CC0000"], strong[style*="color:#cc0000"] {
    color: #e86a64 !important;
  }

  /* ---- Pagination ---- */
  .noindex { color: #c4cdd6 !important; }
  .noindex .select, .select {
    background-color: #21262d !important;
    color: #e86a64 !important;
  }

  /* ---- Help / FAQ boxes ---- */
  .help, .box, .donate {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* ---- Ad slots: darken empty/white iframes so they don't glare ---- */
  /* `syndicatedsearch.goog` is the AdSense-for-Search frame nested inside the forum
     CSE widget. Once an ad is served its document is opaque white and cross-origin,
     i.e. unreachable — this only keeps the UNFILLED slot from glaring. */
  ins.adsbygoogle, .adsbygoogle, iframe[id*="google_ads"],
  iframe[src*="googlesyndication"], iframe[src*="doubleclick"],
  iframe[src*="syndicatedsearch.goog"] {
    background-color: #14181d !important;
  }
  /* AdSense's "Discover more" related-topics unit (`.google-aiuf`) is built in the TOP
     document, not in a cross-origin frame: a row of white pills above the header, plus a
     150x538 white side panel on font pages. Every node inside it carries a 200-property
     inline `!important` style reset — inline importants outrank an author sheet, so no colour
     declaration of ours can reach the pills. The widget root is the one node Google leaves
     alone (its inline style is layout only: no filter, opacity or blend), so the fix has to
     act on the rendered subtree; the hue-rotate keeps Google's link blue reading blue. */
  ins.adsbygoogle .google-aiuf {
    filter: invert(1) hue-rotate(180deg) !important;
  }
  /* Google's reCAPTCHA v3 badge (`login.php`) is a fixed 256x60 tab parked at
     `right:-186px`, so only its logo end shows — a #f9f9f9 plate glaring in the corner.
     Plate and logo are both painted inside a cross-origin google.com iframe, so no
     colour selector of ours reaches them; the wrapper lives in the TOP document and its
     inline style is layout only (no filter, opacity or blend), so a filter on it
     recolours the rendered subtree. The hue-rotate keeps the reCAPTCHA logo blue. */
  .grecaptcha-badge { filter: invert(0.92) hue-rotate(180deg) !important; }

  /* ---- Horizontal rules drawn as repeating raster GIFs ---- */
  /* /img/points.gif is a black dot on transparent (a black dotted rule on the
     white page, invisible on dark); /img/points_test.gif is a SOLID WHITE tile
     used as an invisible spacer on the white page, which paints a glaring white
     band above the footer on dark. Both are background-IMAGES, so the bg-color
     scan reports them clean. Drop the rasters; redraw the real rule in CSS. */
  .points, div[style*="points.gif"], div[style*="points_test.gif"] {
    background-image: none !important;
  }
  .points, div[style*="points.gif"] {
    border-bottom: 1px dotted #2d333b !important;
  }

  /* ---- "Back to top" strip (inline light-grey background) ---- */
  /* A full-width clickable bar above the footer hardcodes background:#e6e6e6;
     darken it to match the elevated surface (its white arrow icons stay visible). */
  .tdn[style*="#e6e6e6"], [style*="background:#e6e6e6"] {
    background: #1c2128 !important;
  }

  /* ---- Brand-red bar text stays white (must outrank our own muted rules) ---- */
  /* The broad `b, strong` and `.dfsmall b` rules above repaint the font name and
     the category headers a muted grey ON the red bar (~3.8:1 — the site ships them
     white). `.dfbg b` ties `.dfsmall b` at (0,2,0), so this block has to come last
     to win on source order. The font-file caption bar recoloured above is the same
     shape without a class: its filename sits in a <b>, so `b, strong` painted it
     #c4cdd6 on the red gradient (3.81:1) while the site ships it white. */
  div[style*="linear-gradient(to right,#c8c8c8"] b,
  div[style*="linear-gradient(to right,#c8c8c8"] strong,
  div[style*="linear-gradient(to right, #c8c8c8"] b,
  div[style*="linear-gradient(to right, #c8c8c8"] strong,
  .dfbg b, .dfbg strong, .metacat b, .metacat strong,
  .lv1left b, .lv1left strong, .lv1right b, .lv1right strong,
  .lv2left b, .lv2left strong,
  .metacat.dfsmall a, .metacat.dfbg a, .dfbg a.tdn, .lv1left a.tdn {
    color: #ffffff !important;
  }

  /* ---- Account-only surfaces (present in DaFont's stylesheet, login-gated) ---- */
  /* `div.notif b {background:#ff3; color:#b00}` is the yellow confirmation banner.
     Our `b, strong` rule repaints its text light grey — 1.9:1 on that yellow. Keep the
     site's dark red. `.pselect {color:#c00}` is the selected preview-size label; raw
     #c00 is only 2.6:1 on our base. Neither renders logged-out, so both are matched
     from DaFont's own base11.css rather than a live element. */
  div.notif b { color: #b00 !important; }
  .pselect { color: #e86a64 !important; }
  /* `.settings {background:#e9e9e9}` is the account-preferences table (its class rule
     is not an inline style, so the #e9e9e9 panel rule above cannot reach it), and the
     forum's read-state chips `span.newflag_index {background:#e9e9e9}` /
     `span.no_index_read a {background:#ccc}` only render once a read cookie exists. */
  .settings { background-color: #1c2128 !important; }
  .settingshead { background-color: #b3322f !important; color: #ffffff !important; }
  span.newflag_index { background-color: #21262d !important; color: #e86a64 !important; }
  span.no_index_read a { background-color: #21262d !important; }
  /* `span.newflag a {background:#c00; color:#fff}` is the unread-posts pill on the
     forum list. Our `a` rule is !important and beats the site's non-important #fff
     whatever the specificity, so the label would render #5fb0e6 on #c00 = 2.4:1.
     `.thumb_user {background:#fff}` is the poster chip overlapping a thread
     thumbnail — a plain white pill. Both need a read cookie, so neither is
     reachable logged-out; matched from forum4.css, same precedent as above. */
  span.newflag a, span.newflag a:hover { color: #ffffff !important; }
  .thumb_user { background-color: #1c2128 !important; }

  /* Forum breadcrumb separator: DaFont's base `div { color:#000 }` leaves this
     arrow glyph pure black — 1.18:1 on the dark page. It carries no own colour
     rule, and it is a single character, so the dark-on-dark scan skips it. */
  .rr { color: #8b949e !important; }

  /* ---- Forum stats page (`/forum/stats.php`) ---- */
  /* The "Identification Topics" pie is an inline Google-Charts <svg> (not an iframe):
     its plot panel and legend box are `rect fill="#ffffff"` and every label is
     `text fill="#000000"`, so the page renders a 478x250 white slab with black type.
     SVG paint attributes are invisible to every background-color/colour audit.
     The slice fills are the same three-hue status key as the forum legend
     (#33dd66 solved / #ffcc33 suggestions / #d4d4d4 none) — data series, keep them
     verbatim; only the chrome moves, including the `stroke="#ffffff"` slice gaps. */
  #chart_div svg rect[fill="#ffffff"] { fill: #1c2128 !important; }
  #chart_div svg text { fill: #c4cdd6 !important; }
  #chart_div svg path[stroke="#ffffff"] { stroke: #1c2128 !important; }
  /* …but the percentage labels are painted ON the slices, i.e. on the light series
     fills, where the site's black is correct and our light grey drops to ~1.2:1 on
     the #d4d4d4 wedge. They are the only <text> that are grandchildren of the <svg>
     (the legend sits three <g> deep), and that extra step wins the cascade. */
  #chart_div svg > g > text { fill: #000000 !important; }
  /* Hovering a slice pops a tooltip drawn INSIDE the same <svg> as a
     `path fill="#ffffff" stroke="#cccccc"` callout — a white card the light label
     above then sits on at ~1.4:1. It does not exist in the DOM until the pointer is
     over a wedge, so no load-time scan reaches it. */
  #chart_div svg g.google-visualization-tooltip path {
    fill: #1c2128 !important;
    stroke: #2d333b !important;
  }

  /* ---- Forum search results (`/forum/search.php`) ---- */
  /* The results are a Google Programmable Search (CSE) widget rendered into a same-origin
     `srcdoc` iframe (`iframe[name="googleSearchFrame"]`), so NOTHING in the top document
     sees it — every scanner reports total=0 while an 800px-wide pure-white slab fills the
     page. The page is reachable only by submitting the forum's search box, which is why
     eight href-enumeration passes never found it: enumerate FORM ACTIONS too.
     Google's `default.css` paints the panel and every result `#fff`, urls `#202124`,
     snippets `#4d5156` and links `#1a0dab` — none of which our selectors named.
     Each result's `border: 1px solid #fff` is an invisible spacer on the white page; the
     blanket border reset already turns it into a visible card edge, and this keeps it —
     a deliberate gain, like the `tr{background:#fff}` zebra on `/forum/?f=2`. */
  .gsc-control-cse, .gsc-results-wrapper-overlay, .gsc-refinementsArea,
  .gsc-webResult.gsc-result, .gsc-webResult.gsc-result:hover,
  .gsc-tabHeader, .gsc-tabHeader.gsc-tabhActive, .gsc-tabHeader.gsc-tabhInactive,
  .gsc-completion-container, .gsc-input-box,
  .gsc-results .gsc-cursor-box .gsc-cursor-page,
  .gsc-results .gsc-cursor-box .gsc-cursor-current-page {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }
  /* A sponsored result is tinted `#f6f6f6` against the organic `#fff` — that tint is the
     only ad disclosure the widget draws, so keep the two surfaces apart on dark too. */
  .gsc-webResult.gsc-result.gsc-promotion { background-color: #1c2128 !important; }
  /* The url line is the site's STRONGEST grey (#202124) and the snippet the mid one
     (#4d5156); preserve that order instead of collapsing both to body text. */
  .gs-webResult .gs-visibleUrl, .gs-promotion .gs-visibleUrl,
  .gs-visibleUrl, .gs-visibleUrl b { color: #e6edf3 !important; }
  .gs-webResult .gs-snippet, .gs-promotion .gs-snippet, .gs-snippet,
  .gs-fileFormatType, .gs-previewSnippet, .gs-previewDescription,
  .gs-spelling {
    color: #c4cdd6 !important;
  }
  .gsc-result-info, .gsc-results .gsc-cursor, .gsc-snippet-metadata,
  .gsc-location, .gsc-tel, .gsc-org, .gsc-author, .gsc-reviewer, .gsc-role {
    color: #8b949e !important;
  }
  /* Google's `#1a0dab` link blue is 1.3:1 here. `.gs-title b` matters twice over: the
     matched query term inside a result title is a <b>, which our own `b, strong` rule
     repaints body-grey — half of every title rendering as prose. */
  .gs-result .gs-title, .gs-result .gs-title *,
  .gs-webResult.gs-result a.gs-title, .gs-webResult.gs-result a.gs-title b,
  .gs-imageResult a.gs-title, .gs-imageResult a.gs-title b,
  .gs-spelling a, .gs-spelling a b, .gs-spelling a i,
  .gs-previewLink, .gs-previewTitle,
  .gcsc-find-more-on-google, .gcsc-find-more-on-google-text,
  .gcsc-find-more-on-google-query {
    color: #5fb0e6 !important;
  }
  /* The magnifier beside "Search <query> on Google" is an inline <svg> whose paint is a
     `fill`, not a `color` — the rule above leaves it navy-on-near-black at 1.3:1. */
  .gcsc-find-more-on-google-magnifier,
  .gcsc-find-more-on-google-magnifier path { fill: #5fb0e6 !important; }
  .gsc-results .gsc-cursor { fill: #8b949e !important; }
  /* "You are here" in the pager and the tab strip is a blue-vs-grey split; the active
     tab's cue is a 3px `#1a0dab` underline the blanket border reset greys out. */
  .gsc-results .gsc-cursor-box .gsc-cursor-page { color: #c4cdd6 !important; }
  .gsc-results .gsc-cursor-box .gsc-cursor-current-page,
  .gsc-tabHeader.gsc-tabhActive, .gsc-refinementHeader.gsc-refinementhActive {
    color: #5fb0e6 !important;
  }
  .gsc-tabHeader.gsc-tabhActive, .gsc-refinementHeader.gsc-refinementhActive {
    border-bottom-color: #5fb0e6 !important;
  }
  .gsc-tabHeader.gsc-tabhInactive, .gsc-refinementHeader.gsc-refinementhInactive {
    color: #c4cdd6 !important;
  }

  /* ---- Tables / generic light cells safety net ---- */
  td[bgcolor="#FFFFFF"], td[bgcolor="#ffffff"], td[bgcolor="white"],
  [style*="background:#fff"], [style*="background-color:#fff"],
  [style*="background:white"] {
    background-color: #1c2128 !important;
  }
}
